27	/**
28	 * Emits the create audit line once the derived membership fields have been populated on the
29	 * response. Highest precedence makes this after-returning advice run last, so it observes the
30	 * membershipLevel and membershipNumber set by the other owner-response advices.
31	 */
32	@Aspect
33	@Component
34	@Order(0)
35	public class OwnerCreateAuditAdvice {
36	
37	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
38	
39	    @AfterReturning(pointcut = "execution(* org.springframework.samples.petclinic.rest.controller.v1."
40	        + "OwnerRestControllerV1.addOwner(..))", returning = "response")
41	    public void auditCreatedOwner(ResponseEntity<?> response) {
42	        if (!(response != null && response.getBody() instanceof OwnerDto owner)) {
43	            return;
44	        }
45	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
46	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
47	            owner.getMembershipLevel(), owner.getMembershipNumber());
48	    }
49	}
