27	/**
28	 * Emits the create audit line once the derived membership fields have been populated on the
29	 * response. Highest precedence makes this after-returning advice run last, so it observes the
30	 * membershipLevel and membershipNumber set by the other owner-response advices.
31	 */
32	@Aspect
33	@Component
34	@Order(0)
35	public class OwnerCreateAuditAdvice {
36	
37	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
