3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Collection;
7	import java.util.Map;
8	import java.util.Objects;
9	import java.util.Set;
10	import java.util.stream.Collectors;
11	
12	import org.springframework.samples.petclinic.model.Owner;
13	
14	/**
15	 * Builds an owner's {@code customerCode} in the format {@code '<REGION>-<HASH8>'}: the region code
16	 * derived from the postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099, then the fixed city
17	 * fallback, else {@code UNKNOWN}) and the first eight upper-case hex characters of SHA-256 over the
18	 * normalized telephone concatenated with the last name. No sequence numbers are used.
19	 */
20	final class CustomerCode {
21	
22	    /** Fixed city-to-region fallback, used only when the postcode identifies no region. */
23	    private static final Map<String, String> CITY_REGION =
24	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
25	
26	    private CustomerCode() {
27	    }
28	
29	    static String of(Owner owner, Collection<Owner> existing) {
30	        String base = region(owner) + "-" + hash8(owner.getTelephone() + owner.getLastName());
31	        return dedupe(base, existing);
32	    }
33	
34	    /** Appends {@code '-<n>'} (smallest {@code n >= 2}) when {@code base} collides with an existing code. */
35	    private static String dedupe(String base, Collection<Owner> existing) {
36	        Set<String> taken = existing.stream().map(Owner::getCustomerCode)
37	            .filter(Objects::nonNull).collect(Collectors.toSet());
38	        String candidate = base;
39	        for (int n = 2; taken.contains(candidate); n++) {
40	            candidate = base + "-" + n;
41	        }
42	        return candidate;
43	    }
44	
45	    private static String region(Owner owner) {
46	        String postcode = owner.getPostcode();
47	        String byPostcode = postcode == null || !postcode.matches("[0-9]{4}") ? null
48	            : switch (Integer.parseInt(postcode) / 100) {
49	                case 20 -> "NSW";
50	                case 30 -> "VIC";
51	                case 40 -> "QLD";
52	                default -> null;
53	            };
54	        return byPostcode != null ? byPostcode : CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
55	    }
56	
57	    private static String hash8(String value) {
58	        StringBuilder sb = new StringBuilder();
59	        for (byte b : sha256(value)) {
60	            sb.append(String.format("%02X", b));
61	        }
62	        return sb.substring(0, 8);
63	    }
64	
65	    private static byte[] sha256(String value) {
66	        try {
67	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
68	        } catch (NoSuchAlgorithmException e) {
69	            throw new IllegalStateException(e);
70	        }
71	    }
72	}
